package com.example.domain.model.i18n

internal object DuaSw1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Kuamka usingizini", "Sifa zote ni za Mwenyezi Mungu aliyetuhuisha baada ya kutufisha (usingizi), na kwake ndiko kurejea.", "Husomwa mara tu baada ya kuamka kwa shukrani kwa Mwenyezi Mungu.", "Nabii ﷺ aliisoma alipoamka — kuanza siku kwa shukrani na kumbukumbu ya akhera."),
        "dua_leaving_home" to DuaText("Kutoka nyumbani", "Kwa jina la Mwenyezi Mungu, nimemtegemea Mwenyezi Mungu, hakuna nguvu wala uwezo isipokuwa kwa Mwenyezi Mungu.", "Husomwa wakati wa kutoka nyumbani kuomba ulinzi.", "Anaambiwa: umeongozwa, umetoshelezwa na umelindwa, na shetani anamwacha."),
        "dua_anxiety_distress" to DuaText("Dua ya wasiwasi na huzuni", "Ewe Mwenyezi Mungu, najikinga kwako na wasiwasi na huzuni, udhaifu na uvivu, ubahili na woga, mzigo wa deni na dhuluma ya watu.", "Wakati wa wasiwasi, huzuni, deni au dhiki ya kiakili.", "Nabii ﷺ aliisoma dua hii mara kwa mara akijikinga na wasiwasi, uvivu na deni."),
        "dua_sayyidul_istighfar" to DuaText("Bwana wa maombi ya msamaha", "Ewe Mwenyezi Mungu, Wewe ni Mola wangu, hapana mungu ila Wewe. Umeniumba na mimi ni mja Wako. Ninashikamana na ahadi Yako kwa uwezo wangu. Najikinga Kwako na uovu wa nilichokitenda. Nakiri neema Yako juu yangu na nakiri dhambi yangu, hivyo nisamehe, kwani hakuna anayesamehe dhambi isipokuwa Wewe.", "Husomwa asubuhi na jioni — dua bora ya toba aliyoifundisha Nabii ﷺ.", "Anayeisoma jioni kwa yakini kisha akafa usiku huo ataingia Peponi; vivyo hivyo asubuhi."),
        "dua_parents" to DuaText("Dua kwa wazazi", "Mola wangu, warehemu kama walivyonilea nikiwa mdogo.", "Dua ya Kurani kwa wazazi kwa malezi yao utotoni.", "Mwenyezi Mungu mwenyewe aliamuru dua hii kwa wazazi katika Kurani."),
        "dua_entering_mosque" to DuaText("Kuingia msikitini", "Ewe Mwenyezi Mungu, nifungulie milango ya rehema Zako.", "Husomwa wakati wa kuingia msikitini kwa mguu wa kulia.", "Nabii ﷺ alifundisha dua hii wakati wa kuingia msikitini."),
        "dua_morning_asbahna" to DuaText("Dhikri ya asubuhi", "Tumeamka na ufalme wa asubuhi hii ni wa Mwenyezi Mungu, sifa zote ni Zake, hapana mungu ila Mwenyezi Mungu peke Yake, hana mshirika, Ufalme ni Wake, sifa ni Zake, na Yeye ni Muweza wa kila kitu.", "Dua ya Sunna inayosomwa asubuhi.", "Kuanza siku kwa kukiri ufalme na upweke wa Mwenyezi Mungu."),
        "dua_evening_amsayna" to DuaText("Dhikri ya jioni", "Tumefika jioni na ufalme wa jioni hii ni wa Mwenyezi Mungu, sifa zote ni Zake, hapana mungu ila Mwenyezi Mungu peke Yake, hana mshirika, Ufalme ni Wake, sifa ni Zake, na Yeye ni Muweza wa kila kitu.", "Dua ya Sunna inayosomwa jioni.", "Kuanza usiku kwa kukiri ufalme na upweke wa Mwenyezi Mungu."),
        "dua_before_sleep" to DuaText("Kabla ya kulala", "Kwa jina Lako ewe Mwenyezi Mungu ninakufa (nalala) na ninaishi (naamka).", "Husomwa baada ya kulala kitandani.", "Nabii ﷺ aliisoma kabla ya kulala."),
        "dua_travel" to DuaText("Dua ya safari", "Ametakasika Yule aliyetutiishia hii, hali sisi tusingeliweza kuitiisha, na hakika sisi kwa Mola wetu ni wenye kurejea.", "Husomwa baada ya kupanda chombo cha usafiri, baada ya takbira mara tatu.", "Dua ya Sunna ya safari kwa ulinzi na baraka."),
        "dua_ayatul_kursi" to DuaText("Aya al-Kursiy baada ya swala", "Mwenyezi Mungu, hapana mungu ila Yeye, aliye hai, Msimamishaji wa vitu vyote. Hashikwi na usingizi wala kulala. Ni Vyake vilivyomo mbinguni na vilivyomo katika ardhi. Ni nani awezaye kuombea mbele Yake bila ya idhini Yake? Anajua yaliyo mbele yao na yaliyo nyuma yao, wala hawalifikii lolote katika ujuzi Wake ila apendavyo. Enzi Yake imeenea mbinguni na katika ardhi, wala hazimshughulishi kuvihifadhi hivyo viwili. Naye ndiye aliye juu, Mkuu.", "Husomwa baada ya kila swala ya faradhi na kabla ya kulala.", "Anayeisoma baada ya kila swala ya faradhi, hakuna kinachomzuia kuingia Peponi isipokuwa kifo; kabla ya kulala, hulindwa hadi asubuhi."),
        "dua_hasbunallah" to DuaText("Mwenyezi Mungu anatutosheleza", "Mwenyezi Mungu anatutosheleza, naye ni Mlinzi mbora.", "Husomwa wakati wa hofu ya adui au hatari kubwa.", "Ibrahim (a.s.) aliisema alipotupwa motoni, na Nabii ﷺ katika hatari."),
        "dua_entering_home" to DuaText("Kuingia nyumbani", "Kwa jina la Mwenyezi Mungu tumeingia, na kwa jina la Mwenyezi Mungu tumetoka, na kwa Mwenyezi Mungu Mola wetu tumetegemea.", "Husomwa wakati wa kuingia nyumbani kwa kutaja jina la Mwenyezi Mungu na salamu.", "Anayemtaja Mwenyezi Mungu anapoingia nyumbani na anapokula, shetani husema: hamna mahali pa kulala wala chakula cha jioni."),
        "dua_yunus" to DuaText("Dua ya Nabii Yunus (a.s.)", "Hapana mungu ila Wewe, umetakasika, hakika mimi nimekuwa miongoni mwa wenye kudhulumu.", "Dua ya Nabii Yunus tumboni mwa samaki — kwa dhiki yoyote.", "Hakuna Muislamu aliyeomba kwa dua hii katika jambo lolote isipokuwa Mwenyezi Mungu alimjibu."),
        "dua_karb" to DuaText("Dua ya dhiki kubwa", "Hapana mungu ila Mwenyezi Mungu, Mkuu, Mpole. Hapana mungu ila Mwenyezi Mungu, Mola wa Arshi kuu. Hapana mungu ila Mwenyezi Mungu, Mola wa mbingu, ardhi na Arshi tukufu.", "Husomwa wakati wa dhiki kubwa na shida.", "Nabii ﷺ aliisoma wakati wa dhiki."),
    )
}
